// @ts-expect-error -- untyped bundle generated by `opennextjs-cloudflare build`
import handler from './.open-next/worker.js'
import { AI_DAILY_TIME_ZONE, publishAiDailyPost } from './lib/ai-daily'

type AiDailyMessage = { now: string; cron: string }
type Env = CloudflareEnv & { AI_DAILY_QUEUE: Queue<AiDailyMessage> }

const hourIn = (timeZone: string, time: number) => {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone, hour: 'numeric', minute: 'numeric', hourCycle: 'h23' })
    .formatToParts(time)
    .reduce<Record<string, string>>((acc, part) => ({ ...acc, [part.type]: part.value }), {})
  return { hour: Number(parts.hour), minute: Number(parts.minute) }
}

export default {
  fetch: (request, env, ctx) => handler.fetch(request, env, ctx),

  // Enqueue at 00:00 and 12:00 in the AI-daily time zone; the queue gives retries + a DLQ.
  scheduled(event, env, ctx) {
    const { hour, minute } = hourIn(AI_DAILY_TIME_ZONE, event.scheduledTime)
    if (minute !== 0 || (hour !== 0 && hour !== 12)) return
    ctx.waitUntil(env.AI_DAILY_QUEUE.send({ now: new Date(event.scheduledTime).toISOString(), cron: event.cron }))
  },

  async queue(batch, env) {
    for (const message of batch.messages) {
      const now = new Date(message.body.now)
      if (Number.isNaN(now.getTime())) {
        console.error('Dropping AI daily message with an invalid timestamp', message.body)
        message.ack()
        continue
      }
      try {
        await publishAiDailyPost({ env, now })
        message.ack()
      } catch (error) {
        console.error('AI daily publish failed', { error, id: message.id, attempts: message.attempts })
        message.retry()
      }
    }
  }
} satisfies ExportedHandler<Env, AiDailyMessage>
